package main

const shellCSS = `
#shell-panel>h4{font-size:15px;margin:18px 0 10px}.shell-command{display:grid;grid-template-columns:minmax(180px,1fr) minmax(0,2fr);gap:16px}.shell-command label{display:flex;flex-direction:column;gap:6px;font-size:12px}.shell-command input,.shell-command textarea{width:100%}#shell-arguments{height:80px;resize:vertical;font:13px/1.5 var(--mono);padding:8px}#terminal-screen{height:370px;background:#17221d;border-radius:8px;padding:12px;margin:12px 0;overflow:hidden;min-width:0}#terminal-screen .xterm{height:100%}#terminal-screen .xterm-viewport{overflow-y:auto}#terminal-state{font:12px/1.5 var(--mono);color:var(--muted)}#shell-job-output{white-space:pre-wrap;overflow-wrap:anywhere;max-height:200px;overflow:auto;font:13px/1.7 var(--mono)}#shell-file-suggestions{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}#shell-file-suggestions button{font:12px var(--mono)}#shell-panel>.runtime-toolbar:first-child,#service-panel>.runtime-toolbar:first-child,#session-panel>.runtime-toolbar:first-child{position:sticky;top:-24px;background:#fff;z-index:1;padding:10px 0;border-bottom:1px solid var(--line)}@media(max-width:650px){.shell-command{grid-template-columns:minmax(0,1fr)}#terminal-screen{height:320px;padding:6px}#shell-panel>.runtime-toolbar:first-child,#service-panel>.runtime-toolbar:first-child,#session-panel>.runtime-toolbar:first-child{top:-16px}}
`

const shellHTML = `
<section id="shell-panel" class="runtime-panel" hidden><div class="runtime-toolbar"><strong>Shell</strong><button class="btn" onclick="refreshShellSessions()">Refresh</button><button class="btn" onclick="closeShellPanel()">Close</button></div><div id="shell-message" class="runtime-status" role="status"></div>
 <div class="session-form"><label class="grow">Shell session<select id="shell-session" onchange="chooseShellSession(this.value)"></select></label><button class="btn" onclick="createShellSession()">New shell</button><label class="grow">Directory<input id="shell-directory" placeholder="Working directory"></label><button class="btn" onclick="changeShellDirectory()">Change directory</button></div>
 <h4>Run a command</h4><div class="shell-command"><label>Program<input id="shell-program" list="shell-commands" placeholder="e.g. ls" oninput="suggestShellCommands()"></label><datalist id="shell-commands"></datalist><label>Arguments · one per line<textarea id="shell-arguments" aria-label="Command arguments" placeholder="Each line is one argument, including spaces."></textarea></label></div><div class="result-actions"><button class="btn btn-run" onclick="runShellCommand(false)">Run command</button><button class="btn" onclick="runShellCommand(true)">Open in terminal</button><button class="btn" onclick="openDefaultTerminal()">Interactive shell</button><button class="btn" onclick="inspectShellSession()">Inspect shell</button></div>
 <details><summary>Add a file argument</summary><label>Path<input id="shell-path" aria-label="File argument prefix" placeholder="Start typing a path" oninput="suggestShellPaths()"></label><div id="shell-file-suggestions"></div></details>
 <div id="shell-command-result"></div><pre id="shell-job-output"></pre>
 <div id="terminal-area" hidden><div class="session-form"><label class="grow">Terminal<select id="terminal-session" onchange="openBrowserTerminal(this.value)"></select></label><button class="btn" onclick="interruptBrowserTerminal()">Interrupt</button><button class="btn" onclick="stopBrowserTerminal()">Stop terminal</button><button class="btn" onclick="inspectBrowserTerminal()">Inspect terminal</button></div><div id="terminal-state" role="status"></div><div id="terminal-screen" aria-label="Interactive terminal"></div></div>
</section>
`

const shellJS = `
let shellPanelVersion=0,shellUIID='',shellJob='',shellCompletionTimer=null,shellCompletionVersion=0,terminalUIID='',terminalRenderedID='',terminalCursor=0,terminalView=null,terminalFit=null,terminalPoll=null,terminalGeneration=0,terminalSending=false,terminalInput='',terminalInputTimer=null,terminalResizeTimer=null,terminalSizeKey='',terminalRunning=false;
function shellMessage(text){document.getElementById('shell-message').textContent=text;}
async function openShellPanel(){closeSession();closeServices();shellPanelVersion++;document.getElementById('shell-panel').hidden=false;await refreshShellSessions();}
function closeShellPanel(){shellPanelVersion++;document.getElementById('shell-panel').hidden=true;clearTimeout(terminalPoll);clearTimeout(terminalInputTimer);clearTimeout(terminalResizeTimer);terminalGeneration++;terminalInput='';terminalRunning=false;terminalView?.dispose();terminalView=null;terminalFit=null;terminalRenderedID='';}
async function refreshShellSessions(){
 const version=shellPanelVersion;if(document.getElementById('shell-panel').hidden)return;else{}
 try{const response=await fetch('/registry').then(response=>response.json());if(version!==shellPanelVersion)return;else{}const select=document.getElementById('shell-session'),terminals=document.getElementById('terminal-session');select.replaceChildren();terminals.replaceChildren();
  for(const entry of response.registry||[]){if(entry.className==='Shell'){const option=toolElement('option','Shell · '+entry.id.slice(0,8));option.value=entry.id;select.append(option);}else if(entry.className==='Terminal'){const option=toolElement('option','Terminal · '+entry.id.slice(0,8));option.value=entry.id;terminals.append(option);}else{}}
  if([...select.options].some(option=>option.value===shellUIID))select.value=shellUIID;else shellUIID=select.value;if(shellUIID)await chooseShellSession(shellUIID);else shellMessage('Create a shell to choose a directory and run commands.');
  if([...terminals.options].some(option=>option.value===terminalUIID))terminals.value=terminalUIID;else{}document.getElementById('terminal-area').hidden=!terminals.options.length;if(version===shellPanelVersion&&terminals.value&&(!terminalView||terminalRenderedID!==terminals.value))await openBrowserTerminal(terminals.value);else{}
 }catch(error){shellMessage(error.message);}
}
async function createShellSession(){try{const result=await performInteraction({kind:'eval',code:'Shell new'});if(result.error)throw Error(result.error);else{}shellUIID=result.result.objid;renderResult(document.getElementById('shell-command-result'),result);await refreshShellSessions();shellMessage('Shell ready.');}catch(error){shellMessage(error.message);}}
async function chooseShellSession(id){shellUIID=id;shellCompletionVersion++;try{const value=await inspectorCall(id,'pwd',[]);if(shellUIID===id)document.getElementById('shell-directory').value=value.str;else{}}catch(error){shellMessage(error.message);}}
async function changeShellDirectory(){const id=shellUIID;try{const result=await performInteraction({kind:'call',objectId:id,method:'cd:',args:[{kind:'string',str:document.getElementById('shell-directory').value}]});if(result.error)throw Error(result.error);else{}if(id===shellUIID){document.getElementById('shell-directory').value=result.result.str;shellMessage('Directory changed.');}else{}}catch(error){shellMessage(error.message);}}
function inspectShellSession(){if(shellUIID){closeShellPanel();showInspect(shellUIID);}else{}}
async function shellArgumentArray(){const text=document.getElementById('shell-arguments').value,args=text===''?[]:text.split('\n'),result=await performInteraction({kind:'eval',code:'{'+args.map(str=>valueExpression({kind:'string',str})).join('. ')+'}'});if(result.error)throw Error(result.error);else{return result.result;}}
async function runShellCommand(terminal){
 if(!shellUIID){shellMessage('Create a shell first.');return;}else{}const id=shellUIID,program=document.getElementById('shell-program').value.trim();if(!program){shellMessage('Enter a program.');return;}else{}
 try{const args=await shellArgumentArray(),result=await performInteraction({kind:'call',objectId:id,method:terminal?'terminal:args:':'exec:args:',args:[{kind:'string',str:program},args]});if(result.error)throw Error(result.error);else{}renderResult(document.getElementById('shell-command-result'),result);if(terminal){terminalUIID=result.result.objid;await refreshShellSessions();if(terminalUIID!==result.result.objid||!terminalView)await openBrowserTerminal(result.result.objid);else{}}else{shellJob=result.result.objid;await refreshShellJob();}shellMessage('Started '+program+'.');}catch(error){shellMessage(error.message);}
}
async function openDefaultTerminal(){
 if(!shellUIID)await createShellSession();else{}if(!shellUIID)return;else{}
 try{const value=await inspectorCall(shellUIID,'env:',[{kind:'string',str:'SHELL'}]);document.getElementById('shell-program').value=value.str||'/bin/sh';document.getElementById('shell-arguments').value='-i';await runShellCommand(true);}catch(error){shellMessage(error.message);}
}
async function refreshShellJob(){if(!shellJob||document.getElementById('shell-panel').hidden)return;else{}const id=shellJob;try{const results=await Promise.all(['status','exitCode','stdout','stderr','error'].map(method=>inspectorCall(id,method,[])));if(id!==shellJob)return;else{}const [status,exit,stdout,stderr,error]=results;document.getElementById('shell-job-output').textContent=status.str+(status.str==='running'?'':' · exit '+fmtVal(exit))+'\n'+(stdout.str||'')+(stderr.str||'')+(error.str?'\n'+error.str:'');}catch(error){shellMessage(error.message);}}
async function shellCompletion(id,method,prefix){const value=await inspectorCall(id,method,[{kind:'string',str:prefix}]);const inspection=await fetch('/relationships?id='+encodeURIComponent(value.objid)).then(response=>response.json());if(inspection.error)throw Error(inspection.error);else{}return Object.entries(inspection.instanceVars||{}).sort((a,b)=>Number(a[0].slice(1,-1))-Number(b[0].slice(1,-1))).map(([,value])=>value.str);}
function suggestShellCommands(){const version=++shellCompletionVersion;clearTimeout(shellCompletionTimer);shellCompletionTimer=setTimeout(async()=>{if(!shellUIID)return;else{}try{const values=await shellCompletion(shellUIID,'completeCommand:',document.getElementById('shell-program').value);if(version!==shellCompletionVersion)return;else{}const list=document.getElementById('shell-commands');list.replaceChildren();for(const value of values.slice(0,100)){const option=toolElement('option',value);option.value=value;list.append(option);}}catch(error){shellMessage(error.message);}},180);}
function suggestShellPaths(){const version=++shellCompletionVersion;clearTimeout(shellCompletionTimer);shellCompletionTimer=setTimeout(async()=>{if(!shellUIID)return;else{}try{const values=await shellCompletion(shellUIID,'completePath:',document.getElementById('shell-path').value);if(version!==shellCompletionVersion)return;else{}const list=document.getElementById('shell-file-suggestions');list.replaceChildren();for(const value of values.slice(0,50))list.append(toolButton(value,()=>{if(value.endsWith('/')){document.getElementById('shell-path').value=value;suggestShellPaths();}else{const args=document.getElementById('shell-arguments');args.value+=(args.value?'\n':'')+value;}}));}catch(error){shellMessage(error.message);}},180);}
async function openBrowserTerminal(id){
 if(!id||document.getElementById('shell-panel').hidden)return;else{}clearTimeout(terminalPoll);clearTimeout(terminalInputTimer);clearTimeout(terminalResizeTimer);terminalGeneration++;terminalUIID=id;terminalRenderedID=id;terminalCursor=0;terminalInput='';terminalSizeKey='';terminalRunning=true;terminalView?.dispose();document.getElementById('terminal-screen').replaceChildren();document.getElementById('terminal-area').hidden=false;document.getElementById('terminal-session').value=id;
 terminalView=new Terminal({cursorBlink:true,convertEol:false,fontFamily:'ui-monospace, monospace',fontSize:13,scrollback:3000,theme:{background:'#17221d',foreground:'#ecf1e9',cursor:'#e7ba85'},allowProposedApi:false});terminalFit=new FitAddon.FitAddon();terminalView.loadAddon(terminalFit);terminalView.open(document.getElementById('terminal-screen'));terminalView.onData(text=>{terminalInput+=text;clearTimeout(terminalInputTimer);terminalInputTimer=setTimeout(sendTerminalInput,20);});terminalView.onResize(()=>resizeBrowserTerminal());terminalFit.fit();terminalView.focus();await pollBrowserTerminal(terminalGeneration);
}
async function sendTerminalInput(){
 if(terminalSending||!terminalInput||!terminalUIID||!terminalView)return;else{}const id=terminalUIID,text=terminalInput,generation=terminalGeneration;terminalInput='';terminalSending=true;
 try{await inspectorCall(id,'write:',[{kind:'string',str:text}]);}catch(error){if(generation===terminalGeneration)document.getElementById('terminal-state').textContent='Input failed: '+error.message;else{}}finally{terminalSending=false;if(terminalInput)sendTerminalInput();else{}}
}
async function resizeBrowserTerminal(){
 clearTimeout(terminalResizeTimer);const id=terminalUIID,columns=terminalView?.cols,rows=terminalView?.rows,generation=terminalGeneration,key=id+':'+columns+':'+rows;if(!id||!columns||!rows||key===terminalSizeKey)return;else{}
 terminalResizeTimer=setTimeout(async()=>{if(generation!==terminalGeneration||!terminalRunning)return;else{}try{await inspectorCall(id,'resizeColumns:rows:',[{kind:'number',num:columns},{kind:'number',num:rows}]);if(generation===terminalGeneration)terminalSizeKey=key;else{}}catch(error){if(generation===terminalGeneration&&terminalRunning)document.getElementById('terminal-state').textContent='Resize failed: '+error.message;else{}}},100);
}
async function pollBrowserTerminal(generation){
 if(generation!==terminalGeneration||document.getElementById('shell-panel').hidden)return;else{}const id=terminalUIID;
 try{const value=await inspectorCall(id,'readFrom:',[{kind:'number',num:terminalCursor}]);if(generation!==terminalGeneration)return;else{}const read=JSON.parse(value.str);terminalRunning=['running','idle','starting'].includes(read.status);if(read.dropped){terminalView.reset();}else{}if(read.data){const bytes=Uint8Array.from(atob(read.data),character=>character.charCodeAt(0));terminalView.write(bytes);}else{}terminalCursor=read.nextOffset;document.getElementById('terminal-state').textContent=read.status+(read.exitCode===null?'':' · exit '+read.exitCode)+(read.dropped?' · '+read.dropped+' older bytes no longer available':'');if(read.data||read.status==='running'||read.status==='idle'||read.status==='starting')terminalPoll=setTimeout(()=>pollBrowserTerminal(generation),read.data?20:150);else{}
 }catch(error){if(generation===terminalGeneration){document.getElementById('terminal-state').textContent=error.message;terminalPoll=setTimeout(()=>pollBrowserTerminal(generation),1000);}else{}}
}
async function interruptBrowserTerminal(){if(!terminalUIID)return;else{}try{const result=await performInteraction({kind:'call',objectId:terminalUIID,method:'interrupt',args:[]});if(result.error)throw Error(result.error);else{}}catch(error){shellMessage(error.message);}}
async function stopBrowserTerminal(){if(!terminalUIID)return;else{}try{const result=await performInteraction({kind:'call',objectId:terminalUIID,method:'stop',args:[]});if(result.error)throw Error(result.error);else{}}catch(error){shellMessage(error.message);}}
function inspectBrowserTerminal(){if(terminalUIID){const id=terminalUIID;closeShellPanel();showInspect(id);}else{}}
const terminalObserver=new ResizeObserver(()=>{if(terminalView&&!document.getElementById('shell-panel').hidden){terminalFit.fit();resizeBrowserTerminal();}else{}});terminalObserver.observe(document.getElementById('terminal-screen'));
setInterval(refreshShellJob,1000);
`
